SELECT 
FROM lots
WHERE status = 'published' AND category_id = #{categoryId} AND id != #{excludeId}
ORDER BY sort
LIMIT #{limit}

SELECT id, lot_id, path_thumb, path_full, alt, caption, sort, wm_x, wm_y, wm_width, wm_opacity
FROM lot_images
WHERE id = #{id}

SELECT id, lot_id, path, poster_path, caption
FROM lot_videos
WHERE lot_id = #{lotId}
